class User:
    def __init__(self, name, role):
        self.name = name
        self.role = role

u = User("sara", "admin")
print(u.name, u.role)

data = [("a.com", 80), ("b.com", 443), ("c.com", 22)]

class Server:
    def __init__(self, host, port):
        self.host = host
        self.port = port

servers = [Server(h, p) for h, p in data]
for s in servers:
    print(s.host + ":" + str(s.port))

